import { Controller, Put, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: 고정자산 연계 대상은 본 시스템 내 회계/고정자산 모듈이며, fixed_asset 저장이 곧 연계다.
const LINK_DONE = '고정자산 모듈 연계 완료';
const DATE_PATTERN = /^\d{4}-\d{2}-\d{2}$/;

function validation(message: string): ApiError {
  return new ApiError(400, 'VALIDATION_FAILED', message);
}

@Controller('api/v1')
export class FnSfr02502Controller {
  @Put('/fixed-assets/:fixedAssetId/depreciation')
  async updateFixedAssetDepreciation(@Req() req: Request) {
    const user = currentUser(req);
    user.require('자산 담당자');
    const data = checks.inputOf(req.body);
    const fixedAssetId = req.params['fixedAssetId'];
    if (!/^\d+$/.test(fixedAssetId)) {
      throw validation('고정자산 ID가 올바르지 않습니다.');
    }
    if (typeof data['isDepreciable'] !== 'boolean') {
      throw validation('상각 여부를 지정하세요.');
    }
    const isDepreciable: boolean = data['isDepreciable'];
    const method = data['depreciationMethod'] ?? null;
    if (method !== null && (typeof method !== 'string' || method.length === 0 || method.length > 50)) {
      throw validation('상각 방법은 50자 이내의 글자여야 합니다.');
    }
    const life = data['usefulLifeYears'] ?? null;
    if (life !== null && (typeof life !== 'number' || !Number.isInteger(life) || life <= 0)) {
      throw validation('내용연수는 1 이상의 정수여야 합니다.');
    }
    const cost = data['acquisitionCost'] ?? null;
    if (cost !== null && (typeof cost !== 'number' || !Number.isFinite(cost) || cost < 0)) {
      throw validation('취득원가는 0 이상의 숫자여야 합니다.');
    }
    const startDate = data['depreciationStartDate'] ?? null;
    if (startDate !== null && (typeof startDate !== 'string' || !DATE_PATTERN.test(startDate))) {
      throw validation('상각 시작일은 YYYY-MM-DD 형식이어야 합니다.');
    }
    return transaction(async (db) => {
      const found = await db.query(
        `SELECT fixed_asset_id AS "fixedAssetId",
                acquisition_cost AS "acquisitionCost"
           FROM fixed_asset
          WHERE fixed_asset_id = CAST(:fixedAssetId AS bigint)
            FOR UPDATE`,
        { fixedAssetId },
      );
      if (found.length === 0) {
        throw new ApiError(404, 'FIXED_ASSET_NOT_FOUND', '자산을 찾을 수 없습니다.');
      }
      if (isDepreciable) {
        const missing: string[] = [];
        if (method === null) {
          missing.push('상각 방법');
        }
        if (life === null) {
          missing.push('내용연수');
        }
        if (startDate === null) {
          missing.push('상각 시작일');
        }
        if (missing.length > 0) {
          throw new ApiError(
            422,
            'DEPRECIATION_INFO_MISSING',
            `상각 대상 자산은 다음 항목을 입력해야 합니다: ${missing.join(', ')}`,
          );
        }
        const check = await db.query(
          `SELECT (CAST(:startDate AS date) >= acquisition_date) AS "ok"
             FROM fixed_asset
            WHERE fixed_asset_id = CAST(:fixedAssetId AS bigint)`,
          { startDate, fixedAssetId },
        );
        if (check[0]['ok'] !== true) {
          throw validation('상각 시작일은 취득일 이후여야 합니다.');
        }
      }
      const rows = await db.query(
        `UPDATE fixed_asset
            SET is_depreciable = :isDepreciable,
                depreciation_method = CAST(:method AS varchar),
                useful_life_years = CAST(:life AS integer),
                acquisition_cost = COALESCE(CAST(:cost AS numeric), acquisition_cost),
                depreciation_start_date = CAST(:startDate AS date),
                updated_at = now()
          WHERE fixed_asset_id = CAST(:fixedAssetId AS bigint)
      RETURNING fixed_asset_id AS "fixedAssetId",
                is_depreciable AS "isDepreciable",
                depreciation_method AS "depreciationMethod",
                useful_life_years AS "usefulLifeYears",
                acquisition_cost AS "acquisitionCost",
                depreciation_start_date AS "depreciationStartDate"`,
        {
          isDepreciable,
          method: isDepreciable ? method : null,
          life: isDepreciable ? life : null,
          cost,
          startDate: isDepreciable ? startDate : null,
          fixedAssetId,
        },
      );
      return { ...rows[0], linkResult: LINK_DONE };
    });
  }
}

