import { useState } from 'react';
import { call, Band, Badge, Num, DateText, DataTable, Drawer, Form, Field, TextInput, NumberInput, DateInput, Select, LookupSelect, RefName, Tiles } from '../kit';
import type { PageProps, Row } from '../kit';

export default function FnSfr02502Page({ role, notify }: PageProps) {
  const [results, setResults] = useState<Row[]>([]);
  const [open, setOpen] = useState(false);
  const [fixedAssetId, setFixedAssetId] = useState<number | string>('');
  const [isDepreciable, setIsDepreciable] = useState('');
  const [method, setMethod] = useState('');
  const [life, setLife] = useState<number | string>('');
  const [cost, setCost] = useState<number | string>('');
  const [startDate, setStartDate] = useState('');

  function openDrawer() {
    setFixedAssetId('');
    setIsDepreciable('');
    setMethod('');
    setLife('');
    setCost('');
    setStartDate('');
    setOpen(true);
  }

  async function submit() {
    if (fixedAssetId === '') {
      throw new Error('고정자산을 선택하세요.');
    }
    if (isDepreciable === '') {
      throw new Error('상각 여부를 선택하세요.');
    }
    const depreciable = isDepreciable === 'true';
    if (depreciable) {
      const missing: string[] = [];
      if (method.trim() === '') {
        missing.push('상각 방법');
      }
      if (life === '') {
        missing.push('내용연수');
      }
      if (startDate === '') {
        missing.push('상각 시작일');
      }
      if (missing.length > 0) {
        throw new Error(`상각 대상은 다음 항목을 입력해야 합니다: ${missing.join(', ')}`);
      }
    }
    const body: Row = { isDepreciable: depreciable };
    if (depreciable) {
      body.depreciationMethod = method.trim();
      body.usefulLifeYears = life;
      body.depreciationStartDate = startDate;
    }
    if (cost !== '') {
      body.acquisitionCost = cost;
    }
    const result = await call('PUT', `/fixed-assets/${fixedAssetId}/depreciation`, role, body);
    setResults([result, ...results]);
    notify('상각정보를 등록하고 고정자산에 연계했습니다.');
    setOpen(false);
  }

  const columns = [
    { key: 'fixedAssetId', label: '고정자산 ID', render: (r: Row) => <RefName table='fixed_asset' role={role} value={r.fixedAssetId} /> },
    { key: 'isDepreciable', label: '상각 여부', render: (r: Row) => <Badge value={r.isDepreciable ? '상각' : '비상각'} /> },
    { key: 'depreciationMethod', label: '상각 방법' },
    { key: 'usefulLifeYears', label: '내용연수', render: (r: Row) => <Num value={r.usefulLifeYears} /> },
    { key: 'acquisitionCost', label: '취득원가', render: (r: Row) => <Num value={r.acquisitionCost} /> },
    { key: 'depreciationStartDate', label: '상각 시작일', render: (r: Row) => <DateText value={r.depreciationStartDate} /> },
    { key: 'linkResult', label: '고정자산 모듈 연계 결과' },
  ];

  const depreciableCount = results.filter((r) => r.isDepreciable === true).length;

  return (
    <div className='bento'>
      <section className='box span-4'>
        <h2>처리 현황</h2>
        <Tiles items={[['처리 건수', <Num value={results.length} />], ['상각 대상', <Num value={depreciableCount} />]]} />
      </section>
      <section className='box span-8'>
        <h2>처리 결과</h2>
        <Band total={results.length}>
          <button type='button' onClick={openDrawer}>상각정보 등록</button>
        </Band>
        <DataTable columns={columns} rows={results} empty='이 화면에서 처리한 내역이 없습니다.' />
      </section>
      {open && (
        <Drawer title='상각정보 등록' onClose={() => setOpen(false)}>
          <Form onSubmit={submit} submit='저장 및 연계'>
            <Field label='고정자산 ID' required>
              <LookupSelect table='fixed_asset' role={role} value={fixedAssetId} onChange={setFixedAssetId} />
            </Field>
            <Field label='상각 여부' required>
              <Select value={isDepreciable} onChange={setIsDepreciable} options={[['true', '상각'], ['false', '비상각']]} />
            </Field>
            <Field label='상각 방법' required={isDepreciable === 'true'}>
              <TextInput value={method} onChange={setMethod} />
            </Field>
            <Field label='내용연수' required={isDepreciable === 'true'}>
              <NumberInput value={life} onChange={setLife} />
            </Field>
            <Field label='취득원가'>
              <NumberInput value={cost} onChange={setCost} />
            </Field>
            <Field label='상각 시작일' required={isDepreciable === 'true'}>
              <DateInput value={startDate} onChange={setStartDate} />
            </Field>
          </Form>
        </Drawer>
      )}
    </div>
  );
}
